ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_funcao_check;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_funcao_check CHECK (funcao IS NULL OR funcao = ANY(ARRAY['medico','enfermeira','enfermeiro','tecnico_enfermagem','cuidador','cuidadora','gerente','fisioterapia','psicologia','nutricao','terapia_ocupacional','fonoaudiologia','servico_social','educacao_fisica','farmacia_clinica','outro','administrador_financeiro']));
CREATE TABLE public.financeiro_acessos (usuario_id uuid PRIMARY KEY REFERENCES public.profiles(id), concedido_por uuid, atualizado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.financeiro_acessos TO authenticated; GRANT ALL ON public.financeiro_acessos TO service_role;
ALTER TABLE public.financeiro_acessos ENABLE ROW LEVEL SECURITY;
CREATE POLICY financeiro_acesso_proprio ON public.financeiro_acessos FOR SELECT TO authenticated USING (usuario_id=auth.uid() OR private.has_role(auth.uid(),'admin'));
CREATE FUNCTION private.financeiro_autorizado() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT auth.uid() IS NOT NULL AND (EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') OR EXISTS (SELECT 1 FROM public.financeiro_acessos a JOIN public.profiles p ON p.id=a.usuario_id WHERE a.usuario_id=auth.uid() AND p.funcao='administrador_financeiro' AND p.status_aprovacao='aprovado')); $$;
REVOKE ALL ON FUNCTION private.financeiro_autorizado() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION private.financeiro_autorizado() TO authenticated,service_role;
CREATE FUNCTION public.financeiro_tem_acesso() RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT private.financeiro_autorizado(); $$;
REVOKE ALL ON FUNCTION public.financeiro_tem_acesso() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.financeiro_tem_acesso() TO authenticated,service_role;
CREATE TABLE public.financeiro_config (id boolean PRIMARY KEY DEFAULT true CHECK(id), multa_bp integer NOT NULL DEFAULT 200 CHECK(multa_bp BETWEEN 0 AND 10000), juros_bp integer NOT NULL DEFAULT 100 CHECK(juros_bp BETWEEN 0 AND 10000), carencia integer NOT NULL DEFAULT 0 CHECK(carencia BETWEEN 0 AND 365), correcao_bp integer NOT NULL DEFAULT 0 CHECK(correcao_bp BETWEEN 0 AND 10000), extras_agrupados boolean NOT NULL DEFAULT true, extras_dia integer CHECK(extras_dia BETWEEN 1 AND 28), alerta_dias integer NOT NULL DEFAULT 3 CHECK(alerta_dias BETWEEN 0 AND 90), inadimplencia_dias integer NOT NULL DEFAULT 30 CHECK(inadimplencia_dias BETWEEN 1 AND 365), mensagem text NOT NULL DEFAULT 'Olá, {responsavel}. A cobrança de {residente}, no valor de {valor}, com vencimento em {vencimento}, está pendente. Por favor, entre em contato com o Residencial São Camilo.', automatico boolean NOT NULL DEFAULT false, atualizado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.financeiro_config TO authenticated; GRANT ALL ON public.financeiro_config TO service_role;
ALTER TABLE public.financeiro_config ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_config_read ON public.financeiro_config FOR SELECT TO authenticated USING(private.financeiro_autorizado());
CREATE TABLE public.financeiro_cadastros (residente_id uuid PRIMARY KEY REFERENCES public.residentes(id), mensalidade_centavos bigint NOT NULL CHECK(mensalidade_centavos BETWEEN 0 AND 1000000000), dia_vencimento integer NOT NULL CHECK(dia_vencimento BETWEEN 1 AND 28), responsavel_nome text NOT NULL, responsavel_telefone text NOT NULL DEFAULT '', forma_preferencial text NOT NULL DEFAULT 'pix', atualizado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.financeiro_cadastros TO authenticated; GRANT ALL ON public.financeiro_cadastros TO service_role;
ALTER TABLE public.financeiro_cadastros ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_cadastros_read ON public.financeiro_cadastros FOR SELECT TO authenticated USING(private.financeiro_autorizado());
CREATE TABLE public.financeiro_catalogo (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nome text NOT NULL CHECK(length(trim(nome))>0), categoria text NOT NULL CHECK(categoria IN ('mensalidade','dieta_suplemento','higiene','bordado','outros')), unidade text NOT NULL DEFAULT 'un', valor_centavos bigint NOT NULL CHECK(valor_centavos BETWEEN 0 AND 1000000000), ativo boolean NOT NULL DEFAULT true, atualizado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.financeiro_catalogo TO authenticated; GRANT ALL ON public.financeiro_catalogo TO service_role;
ALTER TABLE public.financeiro_catalogo ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_catalogo_read ON public.financeiro_catalogo FOR SELECT TO authenticated USING(private.financeiro_autorizado());
CREATE TABLE public.financeiro_cobrancas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), residente_id uuid NOT NULL REFERENCES public.residentes(id), tipo text NOT NULL CHECK(tipo IN ('mensalidade','extras','avulsa')), competencia date NOT NULL, descricao text NOT NULL, valor_centavos bigint NOT NULL DEFAULT 0 CHECK(valor_centavos BETWEEN 0 AND 100000000000), ajuste_centavos bigint NOT NULL DEFAULT 0, emissao date NOT NULL, vencimento date NOT NULL, observacoes text NOT NULL DEFAULT '', cancelada boolean NOT NULL DEFAULT false, motivo_cancelamento text, multa_bp integer NOT NULL, juros_bp integer NOT NULL, carencia integer NOT NULL, correcao_bp integer NOT NULL DEFAULT 0, criado_por uuid, criado_em timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX financeiro_mensalidade_unica ON public.financeiro_cobrancas(residente_id,competencia) WHERE tipo='mensalidade'; CREATE UNIQUE INDEX financeiro_extras_unicos ON public.financeiro_cobrancas(residente_id,competencia) WHERE tipo='extras';
GRANT SELECT ON public.financeiro_cobrancas TO authenticated; GRANT ALL ON public.financeiro_cobrancas TO service_role;
ALTER TABLE public.financeiro_cobrancas ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_cobrancas_read ON public.financeiro_cobrancas FOR SELECT TO authenticated USING(private.financeiro_autorizado());
CREATE TABLE public.financeiro_itens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cobranca_id uuid NOT NULL REFERENCES public.financeiro_cobrancas(id), catalogo_id uuid REFERENCES public.financeiro_catalogo(id), descricao text NOT NULL, categoria text NOT NULL, unidade text NOT NULL, quantidade numeric(12,3) NOT NULL CHECK(quantidade>0), valor_unitario_centavos bigint NOT NULL CHECK(valor_unitario_centavos BETWEEN 0 AND 1000000000), total_centavos bigint NOT NULL CHECK(total_centavos>=0), data_consumo date NOT NULL);
GRANT SELECT ON public.financeiro_itens TO authenticated; GRANT ALL ON public.financeiro_itens TO service_role;
ALTER TABLE public.financeiro_itens ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_itens_read ON public.financeiro_itens FOR SELECT TO authenticated USING(private.financeiro_autorizado());
CREATE TABLE public.financeiro_pagamentos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), residente_id uuid NOT NULL REFERENCES public.residentes(id), data date NOT NULL, valor_centavos bigint NOT NULL CHECK(valor_centavos BETWEEN 1 AND 100000000000), forma text NOT NULL CHECK(forma IN ('pix','dinheiro','transferencia','boleto','cartao','cheque','credito')), observacoes text NOT NULL DEFAULT '', comprovante_path text, fonte_credito uuid REFERENCES public.financeiro_pagamentos(id), estornado boolean NOT NULL DEFAULT false, motivo_estorno text, criado_por uuid, criado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.financeiro_pagamentos TO authenticated; GRANT ALL ON public.financeiro_pagamentos TO service_role;
ALTER TABLE public.financeiro_pagamentos ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_pagamentos_read ON public.financeiro_pagamentos FOR SELECT TO authenticated USING(private.financeiro_autorizado());
CREATE TABLE public.financeiro_alocacoes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pagamento_id uuid NOT NULL REFERENCES public.financeiro_pagamentos(id), cobranca_id uuid NOT NULL REFERENCES public.financeiro_cobrancas(id), principal_centavos bigint NOT NULL DEFAULT 0 CHECK(principal_centavos>=0), multa_centavos bigint NOT NULL DEFAULT 0 CHECK(multa_centavos>=0), juros_centavos bigint NOT NULL DEFAULT 0 CHECK(juros_centavos>=0), correcao_centavos bigint NOT NULL DEFAULT 0 CHECK(correcao_centavos>=0), UNIQUE(pagamento_id,cobranca_id));
GRANT SELECT ON public.financeiro_alocacoes TO authenticated; GRANT ALL ON public.financeiro_alocacoes TO service_role;
ALTER TABLE public.financeiro_alocacoes ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_alocacoes_read ON public.financeiro_alocacoes FOR SELECT TO authenticated USING(private.financeiro_autorizado());
CREATE TABLE public.financeiro_abatimentos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cobranca_id uuid NOT NULL REFERENCES public.financeiro_cobrancas(id), data date NOT NULL, multa_centavos bigint NOT NULL DEFAULT 0, juros_centavos bigint NOT NULL DEFAULT 0, correcao_centavos bigint NOT NULL DEFAULT 0, motivo text NOT NULL CHECK(length(trim(motivo))>0), criado_por uuid, criado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.financeiro_abatimentos TO authenticated; GRANT ALL ON public.financeiro_abatimentos TO service_role;
ALTER TABLE public.financeiro_abatimentos ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_abatimentos_read ON public.financeiro_abatimentos FOR SELECT TO authenticated USING(private.financeiro_autorizado());
CREATE TABLE public.financeiro_contatos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cobranca_id uuid NOT NULL REFERENCES public.financeiro_cobrancas(id), forma text NOT NULL, observacao text NOT NULL DEFAULT '', promessa_data date, criado_por uuid, criado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.financeiro_contatos TO authenticated; GRANT ALL ON public.financeiro_contatos TO service_role;
ALTER TABLE public.financeiro_contatos ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_contatos_read ON public.financeiro_contatos FOR SELECT TO authenticated USING(private.financeiro_autorizado());
CREATE TABLE public.financeiro_caixa (data date PRIMARY KEY, fechado boolean NOT NULL DEFAULT true, motivo text NOT NULL DEFAULT '', atualizado_por uuid, atualizado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.financeiro_caixa TO authenticated; GRANT ALL ON public.financeiro_caixa TO service_role;
ALTER TABLE public.financeiro_caixa ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_caixa_read ON public.financeiro_caixa FOR SELECT TO authenticated USING(private.financeiro_autorizado());
CREATE TABLE public.financeiro_auditoria (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid, usuario_nome text NOT NULL, acao text NOT NULL, entidade text NOT NULL, entidade_id text, antes jsonb, depois jsonb, criado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.financeiro_auditoria TO authenticated; GRANT ALL ON public.financeiro_auditoria TO service_role;
ALTER TABLE public.financeiro_auditoria ENABLE ROW LEVEL SECURITY; CREATE POLICY financeiro_auditoria_read ON public.financeiro_auditoria FOR SELECT TO authenticated USING(private.financeiro_autorizado());
CREATE TABLE public.financeiro_operacoes (id uuid PRIMARY KEY, usuario_id uuid NOT NULL, acao text NOT NULL, resposta jsonb NOT NULL, criado_em timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.financeiro_operacoes TO service_role; ALTER TABLE public.financeiro_operacoes ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION private.financeiro_auditar() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE b jsonb; a jsonb; BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Registros financeiros não podem ser excluídos'; END IF; IF TG_OP='UPDATE' THEN b=to_jsonb(OLD); END IF; a=to_jsonb(NEW); INSERT INTO public.financeiro_auditoria(usuario_id,usuario_nome,acao,entidade,entidade_id,antes,depois) VALUES(auth.uid(),coalesce((SELECT full_name FROM public.profiles WHERE id=auth.uid()),'Rotina automática'),TG_OP,TG_TABLE_NAME,coalesce(a->>'id',a->>'residente_id',a->>'usuario_id',a->>'data'),b,a); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION private.financeiro_auditar() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['financeiro_config','financeiro_cadastros','financeiro_catalogo','financeiro_cobrancas','financeiro_itens','financeiro_pagamentos','financeiro_alocacoes','financeiro_abatimentos','financeiro_contatos','financeiro_caixa'] LOOP EXECUTE format('CREATE TRIGGER financeiro_auditoria AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION private.financeiro_auditar()',t); END LOOP; END $$;
CREATE FUNCTION private.financeiro_sincronizar_funcao() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') THEN RETURN NEW; END IF; IF NEW.funcao='administrador_financeiro' AND NEW.status_aprovacao='aprovado' THEN INSERT INTO public.financeiro_acessos(usuario_id,concedido_por) VALUES(NEW.id,auth.uid()) ON CONFLICT(usuario_id) DO UPDATE SET concedido_por=auth.uid(),atualizado_em=now(); ELSE DELETE FROM public.financeiro_acessos WHERE usuario_id=NEW.id; END IF; IF NEW.funcao IS DISTINCT FROM OLD.funcao OR NEW.status_aprovacao IS DISTINCT FROM OLD.status_aprovacao THEN INSERT INTO public.financeiro_auditoria(usuario_id,usuario_nome,acao,entidade,entidade_id,antes,depois) VALUES(auth.uid(),coalesce((SELECT full_name FROM public.profiles WHERE id=auth.uid()),''),'FUNCAO','profiles',NEW.id::text,jsonb_build_object('funcao',OLD.funcao,'status',OLD.status_aprovacao),jsonb_build_object('funcao',NEW.funcao,'status',NEW.status_aprovacao)); END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION private.financeiro_sincronizar_funcao() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER financeiro_funcao AFTER UPDATE OF funcao,status_aprovacao ON public.profiles FOR EACH ROW EXECUTE FUNCTION private.financeiro_sincronizar_funcao();
CREATE INDEX financeiro_cobrancas_residente ON public.financeiro_cobrancas(residente_id,vencimento); CREATE INDEX financeiro_pagamentos_residente ON public.financeiro_pagamentos(residente_id,data);